import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with an undeclared extra property through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'greet',
        description: 'Greet a person',
        inputSchema: {
          type: 'object',
          properties: {name: {type: 'string'}},
          required: ['name'],
        },
      },
      async input => {
        receivedInput = input;
        return 'hello';
      }
    );

    const response = await registry.execute('greet', {name: 'Alice', extra: 42});

    expect(receivedInput).toEqual({name: 'Alice', extra: 42});
    expect(response.result).toBe('hello');
  });
});

